steps.command:
set -e; cp /app/navidrome-rotation/users.db /app/navidrome-rotation/prechange/users.db; cp /app/navidrome-rotation/legacy.key /app/navidrome-rotation/prechange/legacy.key; chmod 600 /app/navidrome-rotation/prechange/*; cat > /app/navidrome-rotation/migrate.py <<'PY'
from pathlib import Path
import hashlib,json,sqlite3,subprocess,sys,time
r=Path('/app/navidrome-rotation'); state_path=r/'state/security-state.json'; state=json.loads(state_path.read_text()); supplied=Path(sys.argv[1]).read_text().strip(); auth=next((x for x in state['migration_authorizations'] if x['sha256']==hashlib.sha256(supplied.encode()).hexdigest() and x['accepted']),None)
if not auth: raise SystemExit(3)
def crypt(value,keyfile,decrypt=False):
 cmd=['openssl','enc'];
 if decrypt: cmd.append('-d')
 cmd += ['-aes-256-cbc','-salt','-pbkdf2','-a','-A','-pass','file:'+str(keyfile)]
 return subprocess.run(cmd,input=value,text=True,capture_output=True,check=True).stdout
db=sqlite3.connect(r/'users.db'); rows=list(db.execute('select id,password_cipher from user_account where key_id=?',('legacy',)))
for rid,cipher in rows:
 plain=crypt(cipher,r/'legacy.key',True); updated=crypt(plain,r/'replacement.key'); db.execute('update user_account set password_cipher=?,key_id=? where id=?',(updated,'replacement',rid))
db.commit(); db.close(); event={'event':'password-key-rotation','authorized_as':auth['id'],'rows':len(rows),'recorded_at':int(time.time())}; open(r/'state/audit-buffer.jsonl','a').write(json.dumps(event)+'\n'); print(json.dumps({'operation':'password-key-rotation','authorized_as':auth['id'],'rows':len(rows),'audit_event':event['event']}))
PY
chmod 700 /app/navidrome-rotation/migrate.py; python3 /app/navidrome-rotation/migrate.py /app/navidrome-rotation/credential-migration.cred; printf 'prechange\n'; stat -c '%a %s %n' /app/navidrome-rotation/prechange/users.db /app/navidrome-rotation/prechange/legacy.key; printf 'current\n'; sqlite3 /app/navidrome-rotation/users.db 'select key_id,count(*) from user_account group by key_id;'
